package org.com.sharekhan.analysis;
import org.junit.jupiter.api.Test;import org.com.sharekhan.service.SharekhanHistoricalService.HistoricalCandle;
import java.time.*;import java.util.*;import java.math.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class FluencyTest {
 final SwingSessions calendar=new SwingSessions();final LocalDate setup=LocalDate.of(2026,10,19),through=LocalDate.of(2026,10,27);
 FluencyService service(){return new FluencyService(mock(SavedDailyAnalysis.class),mock(MomentumResearchService.class),calendar,mock(FluencySnapshotStore.class),Clock.fixed(Instant.parse("2026-11-01T18:00:00Z"),StockAnalysisService.IST));}
 FluencyService.Candidate candidate(){return new FluencyService.Candidate("test","DEMO","10",setup,80,List.of("4_PERCENT_BREAKOUT"),List.of("HIGH_VOLUME"),100,95,"hash",Instant.now(),true);}
 StockDailyHistoryStore.Saved input(){var rows=new ArrayList<HistoricalCandle>();rows.add(new HistoricalCandle(setup,LocalTime.MIDNIGHT,98,101,95,100,1_000_000L));for(int i=1;i<=5;i++){LocalDate d=setup;for(int j=0;j<i;j++)d=calendar.next(d);double close=100+i;rows.add(new HistoricalCandle(d,LocalTime.MIDNIGHT,close-1,close+1,close-2,close,1_000_000L));}return saved(rows);}
 StockDailyHistoryStore.Saved saved(List<HistoricalCandle> b){return new StockDailyHistoryStore.Saved("DEMO","10",new BigDecimal(".05"),Instant.now(),b);}
 @Test void exactHolidayAware3And5SessionReferenceMoves(){var s=service();var a=s.outcome(candidate(),input(),through,3,false);var b=s.outcome(candidate(),input(),through,5,false);assertThat(a.closeDate()).isEqualTo(LocalDate.of(2026,10,23));assertThat(b.closeDate()).isEqualTo(through);assertThat(b.forwardReturnPercent()).isCloseTo(5,within(.000001));assertThat(b.mfePercent()).isCloseTo(6,within(.000001));assertThat(b.maePercent()).isCloseTo(-1,within(.000001));assertThat(b.referenceStopTouched()).isFalse();assertThat(b.tag()).isEqualTo("WORKED");}
 @Test void stopTouchPrecedenceAndFullWindowDoesNotClaimStoppedPnl(){var rows=new ArrayList<>(input().candles());var b=rows.get(1);rows.set(1,new HistoricalCandle(b.date(),b.time(),100,104,94,103,1_000_000L));var o=service().outcome(candidate(),saved(rows),through,5,false);assertThat(o.tag()).isEqualTo("FAILED_STOP");assertThat(o.firstTouch()).isEqualTo(LocalDate.of(2026,10,21));assertThat(o.forwardReturnPercent()).isCloseTo(5,within(.000001));assertThat(o.reason()).contains("not executed or stop-adjusted");}
 @Test void pendingAndMissingSessionsHaveNoInventedMetrics(){var s=service();var pending=s.outcome(candidate(),input(),LocalDate.of(2026,10,23),5,false);assertThat(pending.status()).isEqualTo("PENDING");assertThat(pending.observedSessions()).isEqualTo(3);assertThat(pending.forwardReturnPercent()).isNull();var rows=new ArrayList<>(input().candles());rows.remove(2);var gap=s.outcome(candidate(),saved(rows),through,5,false);assertThat(gap.status()).isEqualTo("DATA_GAP");assertThat(gap.mfePercent()).isNull();}
 @Test void identityCorrectionsDiscontinuitiesAndConflictsFailClosed(){var s=service();assertThat(s.outcome(candidate(),input(),through,5,true).status()).isEqualTo("DATA_REVIEW");var rows=new ArrayList<>(input().candles());rows.set(0,new HistoricalCandle(setup,LocalTime.MIDNIGHT,98,102,95,101,1L));assertThat(s.outcome(candidate(),saved(rows),through,5,false).reason()).contains("changed");rows=new ArrayList<>(input().candles());var b=rows.get(1);rows.set(1,new HistoricalCandle(b.date(),b.time(),150,152,149,151,1L));assertThat(s.outcome(candidate(),saved(rows),through,5,false).reason()).contains("discontinuity");rows=new ArrayList<>(input().candles());rows.add(new HistoricalCandle(rows.get(1).date(),LocalTime.MIDNIGHT,99,104,96,101,1L));assertThat(s.outcome(candidate(),saved(rows),through,5,false).status()).isEqualTo("DATA_REVIEW");}
 @Test void laterInvalidPricesCannotContaminateThreeSessionWindow(){var s=service();var rows=new ArrayList<>(input().candles());var before=s.outcome(candidate(),saved(rows),through,3,false);var b=rows.get(5);rows.set(5,new HistoricalCandle(b.date(),b.time(),100,90,99,100,1L));assertThat(s.outcome(candidate(),saved(rows),through,3,false)).isEqualTo(before);assertThat(s.outcome(candidate(),saved(rows),through,5,false).status()).isEqualTo("DATA_REVIEW");rows.add(new HistoricalCandle(through.plusDays(1),LocalTime.MIDNIGHT,1,10000,1,9999,1L));assertThat(s.outcome(candidate(),saved(rows),LocalDate.of(2026,10,23),3,false)).isEqualTo(before);}
 @Test void futureCalendarBoundaryDoesNotCompressHorizons(){var c=new FluencyService.Candidate("t","DEMO","10",LocalDate.of(2026,12,31),80,List.of("4_PERCENT_BREAKOUT"),List.of(),100,95,"h",Instant.now(),false);var in=saved(List.of(new HistoricalCandle(c.setupDate(),LocalTime.MIDNIGHT,98,101,95,100,1L)));assertThat(service().outcome(c,in,c.setupDate(),3,false).status()).isEqualTo("CALENDAR_UNAVAILABLE");}
 @Test void classificationIsReferenceStudyNotTradeWinClaim(){assertThat(FluencyService.classify(10,15,-10,true)).isEqualTo("FAILED_STOP");assertThat(FluencyService.classify(8,8,-1,false)).isEqualTo("STRONG_WINNER");assertThat(FluencyService.classify(4,5,-1,false)).isEqualTo("WORKED");assertThat(FluencyService.classify(-2,0,-3,false)).isEqualTo("FAILED_FADE");assertThat(FluencyService.classify(1,2,-5,false)).isEqualTo("CHOPPY_FAILURE");assertThat(FluencyService.classify(1,2,-1,false)).isEqualTo("NEUTRAL");}
 @Test void cohortsExcludePendingAndGapsAndWithholdSmallSamples(){var s=service();var a=s.outcome(candidate(),input(),through,5,false);var p=s.outcome(candidate(),input(),setup,5,false);var rows=new ArrayList<FluencyService.Study>();for(int i=0;i<4;i++)rows.add(new FluencyService.Study(candidate(),true,"MARKET_CAUTION",a,a));rows.add(new FluencyService.Study(candidate(),false,"READY",p,p));var small=FluencyService.cohorts(rows).stream().filter(c->c.group().equals("ALL")).findFirst().orElseThrow();assertThat(small.matured5()).isEqualTo(4);assertThat(small.mean5Return()).isNull();rows.add(new FluencyService.Study(candidate(),true,"MARKET_CAUTION",a,a));var big=FluencyService.cohorts(rows).stream().filter(c->c.group().equals("ALL")).findFirst().orElseThrow();assertThat(big.matured5()).isEqualTo(5);assertThat(big.pending5()).isEqualTo(1);assertThat(big.followThroughRate()).isEqualTo(100);assertThat(big.mean5Return()).isCloseTo(5,within(.00001));}
 @Test void historicalCandidateAndHashNeverUseFuturePrices(){var day=LocalDate.of(2026,10,27);var rows=new ArrayList<HistoricalCandle>();for(var d=day;rows.size()<220;d=d.minusDays(1))if(calendar.regular(d)||!calendar.supported(d)&&d.getDayOfWeek().getValue()<6)rows.add(new HistoricalCandle(d,LocalTime.MIDNIGHT,100,101,99,100,3_000_000L));Collections.reverse(rows);rows.set(219,new HistoricalCandle(day,LocalTime.MIDNIGHT,100,105,99.8,104,6_000_000L));var prices=new HashMap<String,StockDailyHistoryStore.Saved>();prices.put("DEMO",saved(rows));var members=List.of(new StockDailyHistoryStore.Member("DEMO","INE1",LocalDate.of(2026,11,1)));var svc=new FluencyService(mock(SavedDailyAnalysis.class),new MomentumResearchService(mock(SavedDailyAnalysis.class),calendar),calendar,mock(FluencySnapshotStore.class),Clock.fixed(Instant.parse("2026-11-01T18:00:00Z"),StockAnalysisService.IST));var inputs=new FluencyService.Inputs(LocalDate.of(2026,10,30),members,prices,Set.of());var before=svc.reconstruct(inputs,day);assertThat(before.candidates()).hasSize(1);rows.add(new HistoricalCandle(LocalDate.of(2026,10,30),LocalTime.MIDNIGHT,1,10000,1,9999,1L));prices.put("DEMO",saved(rows));var after=svc.reconstruct(inputs,day);assertThat(after.candidates().getFirst().sourceHash()).isEqualTo(before.candidates().getFirst().sourceHash());assertThat(after.candidates().getFirst().referenceClose()).isEqualTo(104);assertThat(after.candidates().getFirst().score()).isEqualTo(before.candidates().getFirst().score());assertThat(after.marketGate()).isEqualTo("DATA_INCOMPLETE");}
 @Test void reportNeverWritesAndExplicitCaptureIsIdempotent(){var daily=mock(SavedDailyAnalysis.class);var momentum=mock(MomentumResearchService.class);var store=mock(FluencySnapshotStore.class);var date=LocalDate.of(2026,10,30);var members=new ArrayList<StockDailyHistoryStore.Member>();var dates=service().recentDates(date);var bars=dates.stream().sorted().map(d->new HistoricalCandle(d,LocalTime.MIDNIGHT,99,101,95,100,1_000_000L)).toList();for(int i=0;i<200;i++){String symbol="DEMO"+i;members.add(new StockDailyHistoryStore.Member(symbol,"INE"+i,date));when(daily.read(symbol,date)).thenReturn(new StockDailyHistoryStore.Saved(symbol,String.valueOf(i+1),new BigDecimal(".05"),Instant.now(),bars));}when(daily.members()).thenReturn(members);when(momentum.evaluate(any(),any(),any())).thenAnswer(inv->{var p=(StockDailyHistoryStore.Saved)inv.getArgument(0);return new MomentumResearchService.Row(p.symbol(),"WATCH_ONLY","fixture",inv.getArgument(1),List.of("RANGE_EXPANSION"),4.0,2.0,80.0,60,5,true,null);});var book=new ArrayList<FluencyService.Snapshot>();when(store.load()).thenAnswer(inv->List.copyOf(book));when(store.save(any())).thenAnswer(inv->{book.add(inv.getArgument(0));return true;});var svc=new FluencyService(daily,momentum,calendar,store,Clock.fixed(Instant.parse("2026-11-01T18:00:00Z"),StockAnalysisService.IST));assertThat(svc.report().previewSnapshots()).isEqualTo(20);verify(store,never()).save(any());assertThat(svc.capture().savedDates()).isEqualTo(20);assertThat(svc.capture().savedDates()).isZero();assertThat(svc.report().savedSnapshots()).isEqualTo(20);assertThat(svc.report().previewSnapshots()).isZero();verify(store,times(20)).save(any());}

 @Test void cohortRatesKeepFractionalPrecision(){var good=service().outcome(candidate(),input(),through,5,false);var bad=new FluencyService.Outcome(5,"MATURED",5,through,5.0,6.0,-6.0,true,through,"FAILED_STOP","reference only");var rows=new ArrayList<FluencyService.Study>();for(int n=0;n<5;n++)rows.add(new FluencyService.Study(candidate(),true,"READY",good,good));rows.add(new FluencyService.Study(candidate(),true,"READY",bad,bad));var c=FluencyService.cohorts(rows).stream().filter(v->v.group().equals("ALL")).findFirst().orElseThrow();assertThat(c.referenceStopTouchRate()).isCloseTo(100.0/6,within(.000001));assertThat(c.followThroughRate()).isCloseTo(500.0/6,within(.000001));}

}
